import crypto from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { format, resolveConfig } from 'prettier'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const generatedHeader =
  'Generated by scripts/interaction-conformance.mjs. Do not edit manually.'

const scenarioFiles = [
  'tests/conformance/interactions/basic-controls.yaml',
  'tests/conformance/interactions/web-first-subset.yaml',
  'tests/conformance/interactions/avalonia-motion.yaml',
  'tests/conformance/interactions/avalonia-overlay.yaml',
]

const outputPaths = {
  traces: 'tests/conformance/interactions/generated/normalized-traces.json',
  runner:
    'tests/conformance/interactions/generated/run-interaction-conformance.mjs',
}

const invalidFixturePath =
  'tests/fixtures/interaction-conformance/invalid-scenarios.json'

const allowedStepTypes = new Set([
  'render',
  'pointer',
  'pointerover',
  'focus',
  'keyboard',
  'assert',
])

const expectationTerms = [
  'accessibleName',
  'checked',
  'duration',
  'emitted',
  'finalState',
  'focusTarget',
  'noOverlap',
  'invalid',
  'modalStack',
  'placement',
  'readonly',
  'restoredFocus',
  'selectedKey',
  'transform',
  'value',
  'zOrder',
]

const read = (relativePath) =>
  fs.readFileSync(path.join(root, relativePath), 'utf8')

const sha256 = (content) =>
  crypto.createHash('sha256').update(content).digest('hex')

const parseScalar = (value) => value.trim().replace(/^['"]|['"]$/g, '')

const parseScenarioFile = (relativePath) => {
  const content = read(relativePath)
  const platform = content.match(/^platform:\s*(\S+)/m)?.[1] ?? 'shared'
  const scenarios = []
  let current
  let currentStep

  const pushStep = () => {
    if (currentStep && current) {
      current.steps.push({
        type: currentStep.type,
        value: currentStep.value.trim(),
      })
    }
    currentStep = undefined
  }

  const pushScenario = () => {
    pushStep()
    if (current) scenarios.push(current)
    current = undefined
  }

  for (const line of content.split('\n')) {
    const scenarioMatch = line.match(/^ {2}- id:\s*(.+)$/)
    if (scenarioMatch) {
      pushScenario()
      current = {
        id: parseScalar(scenarioMatch[1]),
        platform,
        source: relativePath,
        steps: [],
      }
      continue
    }

    if (!current) continue

    const fieldMatch = line.match(/^ {4}([A-Za-z][A-Za-z0-9]*):\s*(.+)$/)
    if (fieldMatch) {
      current[fieldMatch[1]] = parseScalar(fieldMatch[2])
      continue
    }

    const stepMatch = line.match(/^ {6}- ([A-Za-z]+)(?::\s*(.*))?$/)
    if (stepMatch) {
      pushStep()
      currentStep = {
        type: stepMatch[1],
        value: stepMatch[2] ?? '',
      }
      continue
    }

    if (currentStep && line.startsWith('          ')) {
      currentStep.value = `${currentStep.value}\n${line.trim()}`
    }
  }
  pushScenario()

  return scenarios.map(normalizeScenario)
}

const normalizeScenario = (scenario) => {
  validateScenario(scenario)
  const expectations = [
    ...new Set(
      scenario.steps
        .filter((step) => step.type === 'assert')
        .flatMap((step) =>
          expectationTerms.filter((term) => step.value.includes(term)),
        ),
    ),
  ].sort()

  return {
    id: scenario.id,
    platform: scenario.platform,
    component: scenario.component,
    source: scenario.source,
    contract: scenario.contract ?? '',
    motionMode: scenario.motionMode ?? '',
    shardKey: Number.parseInt(sha256(scenario.id).slice(0, 8), 16) % 4,
    steps: scenario.steps,
    expectations,
  }
}

const validateScenario = (scenario) => {
  if (!scenario.id) throw new Error('scenario must include id')
  if (!scenario.component)
    throw new Error(`${scenario.id} must include component`)
  if (!Array.isArray(scenario.steps) || scenario.steps.length === 0) {
    throw new Error(`${scenario.id} must include steps`)
  }

  for (const step of scenario.steps) {
    if (!allowedStepTypes.has(step.type)) {
      throw new Error(`${scenario.id} has unsupported step ${step.type}`)
    }
    if (step.type === 'keyboard' && !step.value) {
      throw new Error(`${scenario.id} keyboard step must include a key`)
    }
  }

  if (!scenario.steps.some((step) => step.type === 'render')) {
    throw new Error(`${scenario.id} must include a render step`)
  }
  if (!scenario.steps.some((step) => step.type === 'assert')) {
    throw new Error(`${scenario.id} must include at least one assert step`)
  }

  const assertText = scenario.steps
    .filter((step) => step.type === 'assert')
    .map((step) => step.value)
    .join('\n')
  if (!expectationTerms.some((term) => assertText.includes(term))) {
    throw new Error(`${scenario.id} must include an expected event or state`)
  }
}

const readScenarios = () => scenarioFiles.flatMap(parseScenarioFile)

const prettierConfig = await resolveConfig(path.join(root, 'package.json'))

const formatGeneratedContent = async (relativePath, content) => {
  if (!/\.(json|mjs|ts)$/.test(relativePath)) return content
  return format(content, {
    ...(prettierConfig ?? {}),
    filepath: path.join(root, relativePath),
  })
}

const renderTraces = (scenarios) =>
  `${JSON.stringify(
    {
      schemaVersion: 1,
      generatedBy: 'scripts/interaction-conformance.mjs',
      note: generatedHeader,
      coveragePolicy: 'planning-only-not-executable-coverage',
      sources: scenarioFiles.map((source) => ({
        path: source,
        sha256: sha256(read(source)),
      })),
      scenarios,
    },
    null,
    2,
  )}\n`

const renderRunner = () => `// ${generatedHeader}
import assert from 'node:assert/strict'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const directory = path.dirname(fileURLToPath(import.meta.url))
const traces = JSON.parse(fs.readFileSync(path.join(directory, 'normalized-traces.json'), 'utf8'))

assert.ok(traces.scenarios.length > 0, 'scenarios must not be empty')
for (const scenario of traces.scenarios) {
  assert.ok(scenario.steps.some((step) => step.type === 'render'), \`\${scenario.id} render step\`)
  assert.ok(scenario.steps.some((step) => step.type === 'assert'), \`\${scenario.id} assert step\`)
  assert.ok(scenario.expectations.length > 0, \`\${scenario.id} expectations\`)
}

assert.equal(traces.coveragePolicy, 'planning-only-not-executable-coverage')

`

const renderAll = async () => {
  const scenarios = readScenarios()
  runInvalidFixtures()
  const files = {
    [outputPaths.traces]: renderTraces(scenarios),
    [outputPaths.runner]: renderRunner(),
  }
  return Object.fromEntries(
    await Promise.all(
      Object.entries(files).map(async ([relativePath, content]) => [
        relativePath,
        await formatGeneratedContent(relativePath, content),
      ]),
    ),
  )
}

const writeFiles = (files) => {
  for (const [relativePath, content] of Object.entries(files)) {
    const absolutePath = path.join(root, relativePath)
    fs.mkdirSync(path.dirname(absolutePath), { recursive: true })
    fs.writeFileSync(absolutePath, content)
    console.log(`wrote ${relativePath}`)
  }
}

const checkFiles = (files) => {
  const failures = []
  for (const [relativePath, expected] of Object.entries(files)) {
    const absolutePath = path.join(root, relativePath)
    if (!fs.existsSync(absolutePath)) {
      failures.push(`${relativePath} is missing`)
      continue
    }
    if (fs.readFileSync(absolutePath, 'utf8') !== expected) {
      failures.push(`${relativePath} is stale`)
    }
  }
  if (failures.length > 0) {
    throw new Error(
      `Interaction conformance artifacts are not current:\n${failures.join('\n')}`,
    )
  }
  execFileSync(process.execPath, [path.join(root, outputPaths.runner)], {
    cwd: root,
    stdio: 'inherit',
  })
  console.log('Interaction conformance artifacts are current.')
}

const runInvalidFixtures = () => {
  const fixture = JSON.parse(read(invalidFixturePath))
  for (const testCase of fixture.cases ?? []) {
    let message = ''
    try {
      validateScenario(testCase.scenario)
    } catch (error) {
      message = error instanceof Error ? error.message : String(error)
    }
    if (!message.includes(testCase.expectedError)) {
      throw new Error(
        `${testCase.name} expected ${testCase.expectedError}, got ${message || 'success'}`,
      )
    }
  }
}

const command = process.argv[2] ?? 'check'

try {
  const files = await renderAll()
  if (command === 'generate') writeFiles(files)
  else if (command === 'check') checkFiles(files)
  else
    throw new Error(
      'Usage: node scripts/interaction-conformance.mjs <generate|check>',
    )
} catch (error) {
  console.error(error instanceof Error ? error.message : error)
  process.exitCode = 1
}
